//! Helpers that reproduce the diagnostics the tool prints when it encounters
//! malformed input (out-of-range indexing and slicing).

use std::io::Write;

/// Print a panic-style diagnostic attributed to `loc` and terminate with the
/// conventional exit code 101.
pub fn panic_at(loc: &str, msg: &str) -> ! {
    let tid = std::process::id();
    let text = format!(
        "\nthread 'main' ({}) panicked at {}:\n{}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n",
        tid, loc, msg
    );
    let stderr = std::io::stderr();
    let mut h = stderr.lock();
    let _ = h.write_all(text.as_bytes());
    let _ = h.flush();
    std::process::exit(101);
}

/// Bounds-checked `buf[a..b]`.
pub fn slice<'a>(buf: &'a [u8], a: usize, b: usize, loc: &str) -> &'a [u8] {
    let len = buf.len();
    if a > len {
        panic_at(
            loc,
            &format!("range start index {} out of range for slice of length {}", a, len),
        );
    }
    if b > len {
        panic_at(
            loc,
            &format!("range end index {} out of range for slice of length {}", b, len),
        );
    }
    if a > b {
        panic_at(loc, &format!("slice index starts at {} but ends at {}", a, b));
    }
    &buf[a..b]
}

/// Bounds check for an element access `buf[idx]` on a container of length `len`.
pub fn check_index(len: usize, idx: usize, loc: &str) {
    if idx >= len {
        panic_at(
            loc,
            &format!("index out of bounds: the len is {} but the index is {}", len, idx),
        );
    }
}
EOF
