//! ELF parsing: header, program headers, section headers, string tables and
//! notes. While parsing, byte ranges of interesting structures are recorded so
//! that the report generator can highlight them in the file dump.

use crate::fail::{check_index, panic_at, slice};
use std::collections::HashMap;

pub const PT_INTERP: u32 = 3;
pub const PT_NOTE: u32 = 4;
pub const SHT_STRTAB: u32 = 3;
pub const SHT_NOBITS: u32 = 8;

/// Highlighted byte ranges. For every file offset we keep the list of span
/// classes opened there (in insertion order) and the number of spans closed
/// after the byte at that offset.
pub struct Ranges {
    file_len: usize,
    starts: HashMap<usize, Vec<String>>,
    ends: HashMap<usize, usize>,
}

impl Ranges {
    fn new(file_len: usize) -> Ranges {
        Ranges {
            file_len,
            starts: HashMap::new(),
            ends: HashMap::new(),
        }
    }

    fn add(&mut self, start: u64, len: u64, class: String) {
        let start = start as usize;
        let last = start.wrapping_add(len as usize).wrapping_sub(1);
        check_index(self.file_len, start, "src/elf/parser.rs:116:18");
        check_index(self.file_len, last, "src/elf/parser.rs:117:18");
        self.starts.entry(start).or_default().push(class);
        *self.ends.entry(last).or_insert(0) += 1;
    }

    pub fn opens_at(&self, pos: usize) -> Option<&Vec<String>> {
        self.starts.get(&pos)
    }

    pub fn closes_at(&self, pos: usize) -> usize {
        self.ends.get(&pos).copied().unwrap_or(0)
    }
}

pub struct Phdr {
    pub p_type: u32,
    pub flags: u32,
    pub offset: u64,
    pub vaddr: u64,
    #[allow(dead_code)]
    pub paddr: u64,
    pub filesz: u64,
    pub memsz: u64,
    pub align: u64,
}

pub struct Shdr {
    pub name: u32,
    pub sh_type: u32,
    pub flags: u64,
    pub addr: u64,
    pub offset: u64,
    pub size: u64,
    pub link: u32,
    pub info: u32,
    pub addralign: u64,
    pub entsize: u64,
}

pub struct Note {
    pub name: Vec<u8>,
    pub desc: Vec<u8>,
    pub n_type: u32,
}

pub struct Elf<'a> {
    pub contents: &'a [u8],
    pub is64: bool,
    pub big_endian: bool,
    pub ident_class: u8,
    pub ident_data: u8,
    pub ident_ver: u8,
    pub ident_abi: u8,
    pub ident_abi_ver: u8,
    pub e_type: u16,
    pub e_machine: u16,
    #[allow(dead_code)]
    pub e_version: u32,
    pub e_entry: u64,
    pub e_phoff: u64,
    pub e_shoff: u64,
    pub e_flags: u32,
    pub e_ehsize: u16,
    pub e_phentsize: u16,
    pub e_phnum: u16,
    pub e_shentsize: u16,
    pub e_shnum: u16,
    pub e_shstrndx: u16,
    pub phdrs: Vec<Phdr>,
    pub shdrs: Vec<Shdr>,
    pub section_names: Vec<String>,
    /// Parsed string lists of STRTAB sections, keyed by section index.
    pub strtabs: HashMap<usize, Vec<String>>,
    pub notes: Vec<Note>,
    pub ranges: Ranges,
}

struct Reader<'a> {
    buf: &'a [u8],
    be: bool,
}

impl<'a> Reader<'a> {
    fn u8(&self, off: usize) -> u8 {
        self.buf[off]
    }
    fn u16(&self, off: usize) -> u16 {
        let b = [self.buf[off], self.buf[off + 1]];
        if self.be {
            u16::from_be_bytes(b)
        } else {
            u16::from_le_bytes(b)
        }
    }
    fn u32(&self, off: usize) -> u32 {
        let mut b = [0u8; 4];
        b.copy_from_slice(&self.buf[off..off + 4]);
        if self.be {
            u32::from_be_bytes(b)
        } else {
            u32::from_le_bytes(b)
        }
    }
    fn u64(&self, off: usize) -> u64 {
        let mut b = [0u8; 8];
        b.copy_from_slice(&self.buf[off..off + 8]);
        if self.be {
            u64::from_be_bytes(b)
        } else {
            u64::from_le_bytes(b)
        }
    }
    /// Word-sized field: 8 bytes for 64-bit files, 4 bytes for 32-bit ones.
    fn word(&self, off: usize, is64: bool) -> u64 {
        if is64 {
            self.u64(off)
        } else {
            self.u32(off) as u64
        }
    }
}

fn read_u32(buf: &[u8], be: bool) -> u32 {
    let mut b = [0u8; 4];
    b.copy_from_slice(&buf[0..4]);
    if be {
        u32::from_be_bytes(b)
    } else {
        u32::from_le_bytes(b)
    }
}

/// Field layout tables: (class name, offset, size).
const EHDR64_FIELDS: [(&str, usize, usize); 13] = [
    ("e_type", 16, 2),
    ("e_machine", 18, 2),
    ("e_version", 20, 4),
    ("e_entry", 24, 8),
    ("e_phoff", 32, 8),
    ("e_shoff", 40, 8),
    ("e_flags", 48, 4),
    ("e_ehsize", 52, 2),
    ("e_phentsize", 54, 2),
    ("e_phnum", 56, 2),
    ("e_shentsize", 58, 2),
    ("e_shnum", 60, 2),
    ("e_shstrndx", 62, 2),
];

const EHDR32_FIELDS: [(&str, usize, usize); 13] = [
    ("e_type", 16, 2),
    ("e_machine", 18, 2),
    ("e_version", 20, 4),
    ("e_entry", 24, 4),
    ("e_phoff", 28, 4),
    ("e_shoff", 32, 4),
    ("e_flags", 36, 4),
    ("e_ehsize", 40, 2),
    ("e_phentsize", 42, 2),
    ("e_phnum", 44, 2),
    ("e_shentsize", 46, 2),
    ("e_shnum", 48, 2),
    ("e_shstrndx", 50, 2),
];

const PHDR64_FIELDS: [(&str, usize, usize); 8] = [
    ("p_type", 0, 4),
    ("p_flags", 4, 4),
    ("p_offset", 8, 8),
    ("p_vaddr", 16, 8),
    ("p_paddr", 24, 8),
    ("p_filesz", 32, 8),
    ("p_memsz", 40, 8),
    ("p_align", 48, 8),
];

const PHDR32_FIELDS: [(&str, usize, usize); 8] = [
    ("p_type", 0, 4),
    ("p_offset", 4, 4),
    ("p_vaddr", 8, 4),
    ("p_paddr", 12, 4),
    ("p_filesz", 16, 4),
    ("p_memsz", 20, 4),
    ("p_flags", 24, 4),
    ("p_align", 28, 4),
];

const SHDR64_FIELDS: [(&str, usize, usize); 10] = [
    ("sh_name", 0, 4),
    ("sh_type", 4, 4),
    ("sh_flags", 8, 8),
    ("sh_addr", 16, 8),
    ("sh_offset", 24, 8),
    ("sh_size", 32, 8),
    ("sh_link", 40, 4),
    ("sh_info", 44, 4),
    ("sh_addralign", 48, 8),
    ("sh_entsize", 56, 8),
];

const SHDR32_FIELDS: [(&str, usize, usize); 10] = [
    ("sh_name", 0, 4),
    ("sh_type", 4, 4),
    ("sh_flags", 8, 4),
    ("sh_addr", 12, 4),
    ("sh_offset", 16, 4),
    ("sh_size", 20, 4),
    ("sh_link", 24, 4),
    ("sh_info", 28, 4),
    ("sh_addralign", 32, 4),
    ("sh_entsize", 36, 4),
];

const IDENT_FIELDS: [(&str, usize, usize); 8] = [
    ("ident", 0, 16),
    ("magic", 0, 4),
    ("class", 4, 1),
    ("data", 5, 1),
    ("ver", 6, 1),
    ("abi", 7, 1),
    ("abi_ver", 8, 1),
    ("pad", 9, 7),
];

/// Split a string table into its strings, the way the report lists them.
/// Empty strings and strings that are not valid UTF-8 are skipped, as is any
/// trailing data that is not NUL-terminated.
fn parse_strtab(data: &[u8]) -> Vec<String> {
    let mut out = Vec::new();
    let mut start = 0usize;
    let mut first = true;
    for (i, &c) in data.iter().enumerate() {
        if c != 0 {
            continue;
        }
        let piece = if first {
            &data[0..i.min(1)]
        } else {
            &data[start..i]
        };
        first = false;
        if let Ok(s) = std::str::from_utf8(piece) {
            if !s.is_empty() {
                out.push(s.to_string());
            }
        }
        start = i + 1;
    }
    out
}

/// Look up a NUL-terminated name in a string table.
fn lookup_name(strtab: &[u8], idx: usize) -> String {
    let mut end = idx;
    loop {
        check_index(strtab.len(), end, "src/elf/parser.rs:384:16");
        if strtab[end] == 0 {
            break;
        }
        end += 1;
    }
    match std::str::from_utf8(&strtab[idx..end]) {
        Ok(s) => s.to_string(),
        Err(_) => String::new(),
    }
}

fn align4(x: usize) -> usize {
    (x + 3) & !3
}

pub fn parse(contents: &[u8]) -> Result<Elf<'_>, String> {
    if contents.len() < 16 {
        return Err("file is smaller than ELF header's e_ident".to_string());
    }
    if &contents[0..4] != b"\x7fELF" {
        return Err("mismatched magic: not an ELF file".to_string());
    }
    let class = contents[4];
    let is64 = match class {
        1 => false,
        2 => true,
        other => return Err(format!("Unknown bitness: {}", other)),
    };
    let data = contents[5];
    let big_endian = match data {
        1 => false,
        2 => true,
        other => return Err(format!("Unknown endianness: {}", other)),
    };
    let ehdr_size = if is64 { 64 } else { 52 };
    if contents.len() < ehdr_size {
        return Err("file is smaller than ELF file header".to_string());
    }

    let rd = Reader {
        buf: contents,
        be: big_endian,
    };

    let e_type = rd.u16(16);
    let e_machine = rd.u16(18);
    let e_version = rd.u32(20);
    let (e_entry, e_phoff, e_shoff, e_flags, rest) = if is64 {
        (rd.u64(24), rd.u64(32), rd.u64(40), rd.u32(48), 52)
    } else {
        (
            rd.u32(24) as u64,
            rd.u32(28) as u64,
            rd.u32(32) as u64,
            rd.u32(36),
            40,
        )
    };
    let e_ehsize = rd.u16(rest);
    let e_phentsize = rd.u16(rest + 2);
    let e_phnum = rd.u16(rest + 4);
    let e_shentsize = rd.u16(rest + 6);
    let e_shnum = rd.u16(rest + 8);
    let e_shstrndx = rd.u16(rest + 10);

    let mut ranges = Ranges::new(contents.len());

    // ELF header and its fields.
    ranges.add(0, e_ehsize as u64, "ehdr".to_string());
    let efields: &[(&str, usize, usize)] = if is64 {
        &EHDR64_FIELDS
    } else {
        &EHDR32_FIELDS
    };
    for &(name, off, size) in efields {
        ranges.add(off as u64, size as u64, name.to_string());
    }

    // Program headers and the segments they describe.
    let phsize: u64 = if is64 { 56 } else { 32 };
    let pfields: &[(&str, usize, usize)] = if is64 {
        &PHDR64_FIELDS
    } else {
        &PHDR32_FIELDS
    };
    let mut phdrs = Vec::new();
    for i in 0..e_phnum as u64 {
        let start = e_phoff.wrapping_add(i.wrapping_mul(phsize));
        let end = start.wrapping_add(phsize);
        let raw = slice(
            contents,
            start as usize,
            end as usize,
            "src/elf/elfxx.rs:174:46",
        );
        let r = Reader {
            buf: raw,
            be: big_endian,
        };
        let ph = if is64 {
            Phdr {
                p_type: r.u32(0),
                flags: r.u32(4),
                offset: r.u64(8),
                vaddr: r.u64(16),
                paddr: r.u64(24),
                filesz: r.u64(32),
                memsz: r.u64(40),
                align: r.u64(48),
            }
        } else {
            Phdr {
                p_type: r.u32(0),
                offset: r.u32(4) as u64,
                vaddr: r.u32(8) as u64,
                paddr: r.u32(12) as u64,
                filesz: r.u32(16) as u64,
                memsz: r.u32(20) as u64,
                flags: r.u32(24),
                align: r.u32(28) as u64,
            }
        };
        if ph.offset != 0 && ph.filesz != 0 {
            ranges.add(ph.offset, ph.filesz, format!("bin_segment{} segment", i));
        }
        ranges.add(start, phsize, format!("bin_phdr{} phdr", i));
        for &(name, off, size) in pfields {
            ranges.add(start.wrapping_add(off as u64), size as u64, name.to_string());
        }
        phdrs.push(ph);
    }

    // Section headers and the sections they describe.
    let shsize: u64 = if is64 { 64 } else { 40 };
    let sfields: &[(&str, usize, usize)] = if is64 {
        &SHDR64_FIELDS
    } else {
        &SHDR32_FIELDS
    };
    let mut shdrs = Vec::new();
    for i in 0..e_shnum as u64 {
        let start = e_shoff.wrapping_add(i.wrapping_mul(shsize));
        let end = start.wrapping_add(shsize);
        let raw = slice(
            contents,
            start as usize,
            end as usize,
            "src/elf/elfxx.rs:227:46",
        );
        let r = Reader {
            buf: raw,
            be: big_endian,
        };
        let sh = Shdr {
            name: r.u32(0),
            sh_type: r.u32(4),
            flags: r.word(8, is64),
            addr: r.word(if is64 { 16 } else { 12 }, is64),
            offset: r.word(if is64 { 24 } else { 16 }, is64),
            size: r.word(if is64 { 32 } else { 20 }, is64),
            link: r.u32(if is64 { 40 } else { 24 }),
            info: r.u32(if is64 { 44 } else { 28 }),
            addralign: r.word(if is64 { 48 } else { 32 }, is64),
            entsize: r.word(if is64 { 56 } else { 36 }, is64),
        };
        if sh.offset != 0 && sh.size != 0 && sh.sh_type != SHT_NOBITS {
            ranges.add(sh.offset, sh.size, format!("bin_section{} section hover", i));
        }
        ranges.add(start, shsize, format!("bin_shdr{} shdr", i));
        for &(name, off, size) in sfields {
            ranges.add(start.wrapping_add(off as u64), size as u64, name.to_string());
        }
        shdrs.push(sh);
    }

    // String tables listed in the section info.
    let mut strtabs = HashMap::new();
    for (i, sh) in shdrs.iter().enumerate() {
        if sh.sh_type != SHT_STRTAB {
            continue;
        }
        let a = sh.offset as usize;
        let b = sh.offset.wrapping_add(sh.size) as usize;
        let data = slice(contents, a, b, "src/elf/parser.rs:274:41");
        strtabs.insert(i, parse_strtab(data));
    }

    // Section header string table.
    let mut shstrtab: Option<&[u8]> = None;
    if e_shstrndx != 0 && (e_shstrndx as usize) < shdrs.len() {
        let sh = &shdrs[e_shstrndx as usize];
        let a = sh.offset as usize;
        let b = sh.offset.wrapping_add(sh.size) as usize;
        let data = slice(contents, a, b, "src/elf/parser.rs:283:41");
        if !data.is_empty() {
            shstrtab = Some(data);
        }
    }

    // e_ident fields.
    for &(name, off, size) in IDENT_FIELDS.iter() {
        ranges.add(off as u64, size as u64, name.to_string());
    }

    // Notes contained in PT_NOTE segments.
    let mut notes = Vec::new();
    for ph in phdrs.iter() {
        if ph.p_type != PT_NOTE {
            continue;
        }
        let a = ph.offset as usize;
        let b = ph.offset.wrapping_add(ph.filesz) as usize;
        let seg = slice(contents, a, b, "src/elf/parser.rs:306:34");
        let mut pos = 0usize;
        while pos < seg.len() {
            let rest = &seg[pos..];
            let namesz = read_u32(slice(rest, 0, 4, "src/elf/parser.rs:351:39"), big_endian) as usize;
            let descsz = read_u32(slice(rest, 4, 8, "src/elf/parser.rs:352:39"), big_endian) as usize;
            let n_type = read_u32(slice(rest, 8, 12, "src/elf/parser.rs:353:39"), big_endian);
            let total = 12 + namesz + descsz;
            if total > rest.len() {
                break;
            }
            let name_full = &rest[12..12 + namesz];
            let name = if namesz > 0 {
                name_full[..namesz - 1].to_vec()
            } else {
                Vec::new()
            };
            let desc = rest[12 + namesz..12 + namesz + descsz].to_vec();
            let len = align4(total);
            ranges.add(
                (a.wrapping_add(pos)) as u64,
                len as u64,
                "segment_subrange hover".to_string(),
            );
            notes.push(Note { name, desc, n_type });
            pos += len;
        }
    }

    // Section names.
    let mut section_names = Vec::with_capacity(shdrs.len());
    for sh in shdrs.iter() {
        let name = match shstrtab {
            Some(tab) => lookup_name(tab, sh.name as usize),
            None => String::new(),
        };
        section_names.push(name);
    }

    if false {
        panic_at("", "");
    }

    Ok(Elf {
        contents,
        is64,
        big_endian,
        ident_class: class,
        ident_data: data,
        ident_ver: rd.u8(6),
        ident_abi: rd.u8(7),
        ident_abi_ver: rd.u8(8),
        e_type,
        e_machine,
        e_version,
        e_entry,
        e_phoff,
        e_shoff,
        e_flags,
        e_ehsize,
        e_phentsize,
        e_phnum,
        e_shentsize,
        e_shnum,
        e_shstrndx,
        phdrs,
        shdrs,
        section_names,
        strtabs,
        notes,
        ranges,
    })
}
EOF
echo ok"}

