    pub e_phoff: u64,
    pub e_shoff: u64,
    pub e_flags: u32,
    pub e_ehsize: u16,
    pub e_phentsize: u16,
    pub e_phnum: u16,
    pub e_shentsize: u16,
    pub e_shnum: u16,
    pub e_shstrndx: u16,
    pub phdrs: Vec<Phdr>,
    pub shdrs: Vec<Shdr>,
    pub section_names: Vec<String>,
    /// Parsed string lists of STRTAB sections, keyed by section index.
    pub strtabs: HashMap<usize, Vec<String>>,
    pub notes: Vec<Note>,
    pub ranges: Ranges,
}

struct Reader<'a> {
    buf: &'a [u8],
    be: bool,
}

impl<'a> Reader<'a> {
    fn u8(&self, off: usize) -> u8 {
        self.buf[off]
    }
    fn u16(&self, off: usize) -> u16 {
        let b = [self.buf[off], self.buf[off + 1]];
        if self.be {
            u16::from_be_bytes(b)
        } else {
            u16::from_le_bytes(b)
        }
    }
    fn u32(&self, off: usize) -> u32 {
        let mut b = [0u8; 4];
        b.copy_from_slice(&self.buf[off..off + 4]);
        if self.be {
            u32::from_be_bytes(b)
        } else {
            u32::from_le_bytes(b)
        }
    }
    fn u64(&self, off: usize) -> u64 {
        let mut b = [0u8; 8];
        b.copy_from_slice(&self.buf[off..off + 8]);
        if self.be {
            u64::from_be_bytes(b)
        } else {
            u64::from_le_bytes(b)
        }
    }
    /// Word-sized field: 8 bytes for 64-bit files, 4 bytes for 32-bit ones.
    fn word(&self, off: usize, is64: bool) -> u64 {
        if is64 {
            self.u64(off)
        } else {
            self.u32(off) as u64
        }
    }
}

fn read_u32(buf: &[u8], be: bool) -> u32 {
    let mut b = [0u8; 4];
    b.copy_from_slice(&buf[0..4]);
    if be {
