//! HTML report generation.

use crate::elf::{Elf, Phdr, Shdr, PT_INTERP, PT_NOTE, SHT_STRTAB};
use crate::fail::slice;
use std::fmt::Write;

const HEAD1: &str = include_str!("tpl/head1.html");
const HEAD2: &str = include_str!("tpl/head2.html");
const SCRIPTS1: &str = include_str!("tpl/scripts1.html");
const OFFSETS_SCRIPT: &str = include_str!("tpl/offsets_script.html");
const ARROWS1: &str = include_str!("tpl/arrows1.html");
const TAIL: &str = include_str!("tpl/tail.html");

const UNITS: [&str; 6] = ["KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];

/// "26.3 KiB"-style rendering of a byte count that is at least 1024.
fn human_units(n: u64) -> String {
    let mut idx = 0;
    let mut div: u64 = 1024;
    while idx + 1 < UNITS.len() && n >= div.saturating_mul(1024) && div <= u64::MAX / 1024 {
        div *= 1024;
        idx += 1;
    }
    format!("{:.1} {}", n as f64 / div as f64, UNITS[idx])
}

fn file_size_str(n: u64) -> String {
    if n < 1024 {
        format!("{} B", n)
    } else {
        format!("{} ({} B)", human_units(n), n)
    }
}

fn num_hex(n: u64) -> String {
    format!("<span class='number' title='{}'>0x{:x}</span>", n, n)
}

fn num_dec(n: u64) -> String {
    format!("<span class='number' title='0x{:x}'>{}</span>", n, n)
}

fn num_size(n: u64) -> String {
    if n < 1024 {
        num_dec(n)
    } else {
        format!(
            "<span class='number' title='0x{:x}'>{} ({})</span>",
            n,
            n,
            human_units(n)
        )
    }
}

/// Printable characters are shown as-is, everything else as a bold hex byte.
fn fmt_bytes(data: &[u8]) -> String {
    let mut s = String::new();
    for &b in data {
        if b.is_ascii_graphic() {
            s.push(b as char);
        } else {
            let _ = write!(s, "<b>{:02x}</b> ", b);
        }
    }
    s
}

