    let mut s = String::new();
    if f & 1 != 0 {
        s.push('W');
    }
    if f & 2 != 0 {
        s.push('A');
    }
    if f & 4 != 0 {
        s.push('X');
    }
    if s.is_empty() {
        s.push('0');
    }
    s
}

fn row(out: &mut String, class: &str, label: &str, value: &str) {
    let _ = writeln!(
        out,
        "      <tr class='{}'> <td>{}</td> <td>{}</td> </tr>",
        class, label, value
    );
}

fn file_info(out: &mut String, elf: &Elf, path: &str) {
    out.push_str("    <table>\n");
    row(out, "fileinfo_file_name", "File name:", path);
    row(
        out,
        "fileinfo_file_size",
        "File size:",
        &file_size_str(elf.contents.len() as u64),
    );
    row(
        out,
        "fileinfo_class",
        "Object class:",
        if elf.is64 { "64-bit" } else { "32-bit" },
    );
    row(
        out,
        "fileinfo_data",
        "Data encoding:",
        if elf.big_endian {
            "Big endian"
        } else {
            "Little endian"
        },
    );
    if elf.ident_ver != 1 {
        row(
            out,
            "fileinfo_ver",
            "Uncommon version(!):",
            &elf.ident_ver.to_string(),
        );
    }
    if elf.ident_abi == 0 {
        row(out, "fileinfo_abi", "ABI:", "SysV");
        if elf.ident_abi_ver != 0 {
            row(
                out,
                "fileinfo_abi_ver",
                "Uncommon ABI version(!):",
                &elf.ident_abi_ver.to_string(),
            );
        }
    } else {
        row(
            out,
            "fileinfo_abi",
            "Uncommon ABI(!):",
            &abi_name(elf.ident_abi),
        );
        row(
            out,
            "fileinfo_abi_ver",
            "ABI version:",
            &elf.ident_abi_ver.to_string(),
        );
    }
    row(out, "fileinfo_e_type", "Type:", &e_type_name(elf.e_type));
    row(
        out,
        "fileinfo_e_machine",
        "Architecture:",
        &machine_name(elf.e_machine),
    );
    row(out, "fileinfo_e_entry", "Entrypoint:", &num_hex(elf.e_entry));
    let ph = format!(
        "<span title='0x{:x}' class='number fileinfo_e_phnum'>{}</span> * \
         <span title='0x{:x}' class='number fileinfo_e_phentsize'>{}</span> @ \
         <span title='0x{:x}' class='number fileinfo_e_phoff'>{}</span>",
        elf.e_phnum, elf.e_phnum, elf.e_phentsize, elf.e_phentsize, elf.e_phoff, elf.e_phoff
    );
    row(out, "fileinfo_ph", "Program headers:", &ph);
    let sh = format!(
        "<span title='0x{:x}' class='number fileinfo_e_shnum'>{}</span> * \
         <span title='0x{:x}' class='number fileinfo_e_shentsize'>{}</span> @ \
         <span title='0x{:x}' class='number fileinfo_e_shoff'>{}</span>",
        elf.e_shnum, elf.e_shnum, elf.e_shentsize, elf.e_shentsize, elf.e_shoff, elf.e_shoff
    );
    row(out, "fileinfo_sh", "Section headers:", &sh);
