    out.push_str("    </table>\n");
}

fn offsets_column(out: &mut String, len: usize) {
    out.push_str("    <div id='offsets'>");
    for i in (0..len).step_by(16) {
        let _ = write!(out, "{:x}", i);
        if i + 16 <= len {
            out.push('\n');
        }
    }
    out.push_str("</div>\n");
}

const HEX: &[u8; 16] = b"0123456789abcdef";

fn bytes_column(out: &mut String, elf: &Elf) {
    out.push_str("    <div id='bytes'>");
    let contents = elf.contents;
    for (i, &b) in contents.iter().enumerate() {
        if i > 0 {
            out.push(if i % 16 == 0 { '\n' } else { ' ' });
        }
        if let Some(classes) = elf.ranges.opens_at(i) {
            for c in classes {
                out.push_str("<span class='");
                out.push_str(c);
                out.push_str("'>");
            }
        }
        if (1..4).contains(&i) {
            out.push_str("&nbsp;");
            out.push(b as char);
        } else {
            out.push(HEX[(b >> 4) as usize] as char);
            out.push(HEX[(b & 15) as usize] as char);
        }
        for _ in 0..elf.ranges.closes_at(i) {
            out.push_str("</span>");
        }
    }
    out.push_str("</div>\n");
}

fn ascii_column(out: &mut String, contents: &[u8]) {
    out.push_str("    <div id='ascii'>");
    for (i, &b) in contents.iter().enumerate() {
        match b {
            b'<' => out.push_str("&lt;"),
            b'>' => out.push_str("&gt;"),
            b'&' => out.push_str("&amp;"),
            b'"' => out.push_str("&quot;"),
            b'\'' => out.push_str("&apos;"),
            _ if b.is_ascii_graphic() => out.push(b as char),
            _ => out.push('.'),
        }
        if i % 16 == 15 {
            out.push('\n');
        }
    }
    out.push_str("</div>\n");
}

fn trow(out: &mut String, label: &str, value: &str) {
    let _ = writeln!(
        out,
        "            <tr> <td>{}</td> <td>{}</td> </tr>",
        label, value
    );
}

fn table_open(out: &mut String, id: &str, th_class: &str) {
    let _ = writeln!(out, "          <table class='conceal itable' id='{}'>", id);
    let _ = writeln!(out, "          <th colspan='2' class='{}'></th>", th_class);
}

fn table_close(out: &mut String) {
    out.push_str("          </table>\n");
}

fn phdr_table(out: &mut String, i: usize, ph: &Phdr) {
    table_open(out, &format!("info_phdr{}", i), "phdr_itable");
    trow(out, "Type:", &p_type_name(ph.p_type));
    trow(out, "Flags:", &p_flags_str(ph.flags));
    trow(out, "Offset in file:", &num_hex(ph.offset));
    trow(out, "Size in file:", &num_size(ph.filesz));
    trow(out, "Vaddr in memory:", &num_hex(ph.vaddr));
    trow(out, "Size in memory:", &num_size(ph.memsz));
    trow(out, "Alignment:", &num_hex(ph.align));
    table_close(out);
}

fn shdr_table(out: &mut String, i: usize, sh: &Shdr, name: &str) {
    table_open(out, &format!("info_shdr{}", i), "shdr_itable");
    trow(out, "Index:", &i.to_string());
    trow(out, "Name:", name);
    trow(out, "Type:", &sh_type_name(sh.sh_type));
    trow(out, "Flags:", &sh_flags_str(sh.flags));
    trow(out, "Vaddr in memory:", &num_hex(sh.addr));
    trow(out, "Offset in file:", &num_hex(sh.offset));
    trow(out, "Size in file:", &num_size(sh.size));
    trow(out, "Linked section:", &sh.link.to_string());
    trow(out, "Extra info:", &num_dec(sh.info as u64));
    trow(out, "Alignment:", &num_hex(sh.addralign));
    trow(out, "Size of entries:", &num_size(sh.entsize));
    table_close(out);
}

fn segment_table(out: &mut String, i: usize, ph: &Phdr, elf: &Elf) {
    table_open(out, &format!("info_segment{}", i), "segment_itable");
    trow(out, "Type:", &p_type_name(ph.p_type));
    trow(out, "Size in file:", &num_size(ph.filesz));
    trow(out, "Size in memory:", &num_size(ph.memsz));
    if ph.p_type == PT_INTERP {
        let a = ph.offset as usize;
        let b = ph.offset.wrapping_add(ph.filesz).wrapping_sub(1) as usize;
        let interp = slice(elf.contents, a, b, "src/report_gen.rs:266:30");
        out.push_str("            <tr><td><br></td></tr>\n");
        trow(out, "Interpreter:", &fmt_bytes(interp));
    }
    if ph.p_type == PT_NOTE {
        out.push_str("            <tr><td><br></td></tr>\n");
        for (n, note) in elf.notes.iter().enumerate() {
            if n > 0 {
                out.push_str("            <tr> <td><br></td> </tr>\n");
            }
            trow(out, "Name:", &fmt_bytes(&note.name));
            trow(out, "Type:", &format!("0x{:x}", note.n_type));
            if note.n_type == 3 {
                let mut hex = String::with_capacity(note.desc.len() * 2);
                for b in &note.desc {
                    let _ = write!(hex, "{:02x}", b);
                }
                trow(out, "Build ID:", &hex);
            } else {
                trow(out, "Desc:", &fmt_bytes(&note.desc));
            }
        }
    }
    table_close(out);
}

fn section_table(out: &mut String, i: usize, sh: &Shdr, elf: &Elf) {
    table_open(out, &format!("info_section{}", i), "section_itable");
    trow(out, "Type:", &sh_type_name(sh.sh_type));
    trow(out, "Size:", &num_size(sh.size));
    if sh.sh_type == SHT_STRTAB {
        out.push_str("            <tr><td><br></td></tr>\n");
        out.push_str("            <tr>\n");
        out.push_str("              <td></td>\n");
        out.push_str("              <td>\n");
        out.push_str("                <div>\n");
        if let Some(strings) = elf.strtabs.get(&i) {
            for s in strings {
                let _ = writeln!(out, "                  {}", s);
            }
        }
        out.push_str("                </div>\n");
        out.push_str("              </td>\n");
        out.push_str("            </tr>\n");
    }
    table_close(out);
}

fn info_tables(out: &mut String, elf: &Elf) {
    out.push_str("    <table id='sticky_table' cellspacing='0'>\n");
    out.push_str("      <tr>\n");
    out.push_str("        <td id='desc'></td>\n");
    out.push_str("        <td class='infotables'>\n");
    for (i, ph) in elf.phdrs.iter().enumerate() {
        phdr_table(out, i, ph);
    }
    for (i, sh) in elf.shdrs.iter().enumerate() {
        shdr_table(out, i, sh, &elf.section_names[i]);
    }
    out.push_str("        </td>\n");
    out.push_str("        <td class='infotables'>\n");
    for (i, ph) in elf.phdrs.iter().enumerate() {
        segment_table(out, i, ph, elf);
    }
    for (i, sh) in elf.shdrs.iter().enumerate() {
        section_table(out, i, sh, elf);
    }
    out.push_str("        </td>\n");
    out.push_str("      </tr>\n");
    out.push_str("    </table>\n");
}

fn arrows(out: &mut String, elf: &Elf) {
    out.push_str("      connect('.e_phoff', '.bin_phdr0');\n");
    out.push_str("      connect('.e_shoff', '.bin_shdr0');\n");
    for i in 0..elf.phdrs.len() {
        let _ = writeln!(
            out,
            "      connect('.bin_phdr{} > .p_offset', '.bin_segment{}');",
            i, i
        );
    }
    for (i, sh) in elf.shdrs.iter().enumerate() {
        let _ = writeln!(
            out,
            "      connect('.bin_shdr{} > .sh_offset', '.bin_section{}');",
            i, i
        );
        if sh.link != 0 {
            let _ = writeln!(
                out,
                "      connect('.bin_shdr{} > .sh_link', '.bin_shdr{}');",
                i, sh.link
            );
        }
    }
}

pub fn generate(elf: &Elf, path: &str, title: &str) -> String {
    let len = elf.contents.len();
    let mut out = String::with_capacity(len * 6 + 64 * 1024);
    out.push_str(HEAD1);
    let _ = writeln!(out, "    <title>{}</title>", title);
    out.push_str(HEAD2);
    file_info(&mut out, elf, path);
    offsets_column(&mut out, len);
    bytes_column(&mut out, elf);
    ascii_column(&mut out, elf.contents);
    info_tables(&mut out, elf);
    out.push_str(SCRIPTS1);
    out.push_str("    <script type='text/javascript'>\n");
    let _ = writeln!(out, "      let fileLen = {}", len);
    out.push_str(OFFSETS_SCRIPT);
    out.push_str(ARROWS1);
    arrows(&mut out, elf);
    out.push_str(TAIL);
    out
}
