        if i + 16 <= len {
            out.push('\n');
        }
    }
    out.push_str("</div>\n");
}

const HEX: &[u8; 16] = b"0123456789abcdef";

fn bytes_column(out: &mut String, elf: &Elf) {
    out.push_str("    <div id='bytes'>");
    let contents = elf.contents;
    for (i, &b) in contents.iter().enumerate() {
        if i > 0 {
            out.push(if i % 16 == 0 { '\n' } else { ' ' });
        }
        if let Some(classes) = elf.ranges.opens_at(i) {
            for c in classes {
                out.push_str("<span class='");
                out.push_str(c);
                out.push_str("'>");
            }
        }
        if (1..4).contains(&i) {
            out.push_str("&nbsp;");
            out.push(b as char);
        } else {
            out.push(HEX[(b >> 4) as usize] as char);
            out.push(HEX[(b & 15) as usize] as char);
        }
        for _ in 0..elf.ranges.closes_at(i) {
            out.push_str("</span>");
        }
    }
    out.push_str("</div>\n");
