            trow(out, "Name:", &fmt_bytes(&note.name));
            trow(out, "Type:", &format!("0x{:x}", note.n_type));
            if note.n_type == 3 {
                let mut hex = String::with_capacity(note.desc.len() * 2);
                for b in &note.desc {
                    let _ = write!(hex, "{:02x}", b);
                }
                trow(out, "Build ID:", &hex);
            } else {
                trow(out, "Desc:", &fmt_bytes(&note.desc));
            }
        }
    }
    table_close(out);
}

fn section_table(out: &mut String, i: usize, sh: &Shdr, elf: &Elf) {
    table_open(out, &format!("info_section{}", i), "section_itable");
    trow(out, "Type:", &sh_type_name(sh.sh_type));
    trow(out, "Size:", &num_size(sh.size));
    if sh.sh_type == SHT_STRTAB {
        out.push_str("            <tr><td><br></td></tr>\n");
        out.push_str("            <tr>\n");
        out.push_str("              <td></td>\n");
        out.push_str("              <td>\n");
        out.push_str("                <div>\n");
        if let Some(strings) = elf.strtabs.get(&i) {
            for s in strings {
                let _ = writeln!(out, "                  {}", s);
            }
        }
        out.push_str("                </div>\n");
        out.push_str("              </td>\n");
        out.push_str("            </tr>\n");
    }
    table_close(out);
}

fn info_tables(out: &mut String, elf: &Elf) {
    out.push_str("    <table id='sticky_table' cellspacing='0'>\n");
    out.push_str("      <tr>\n");
    out.push_str("        <td id='desc'></td>\n");
    out.push_str("        <td class='infotables'>\n");
    for (i, ph) in elf.phdrs.iter().enumerate() {
        phdr_table(out, i, ph);
    }
    for (i, sh) in elf.shdrs.iter().enumerate() {
        shdr_table(out, i, sh, &elf.section_names[i]);
    }
    out.push_str("        </td>\n");
    out.push_str("        <td class='infotables'>\n");
    for (i, ph) in elf.phdrs.iter().enumerate() {
        segment_table(out, i, ph, elf);
    }
    for (i, sh) in elf.shdrs.iter().enumerate() {
        section_table(out, i, sh, elf);
    }
    out.push_str("        </td>\n");
    out.push_str("      </tr>\n");
    out.push_str("    </table>\n");
}

fn arrows(out: &mut String, elf: &Elf) {
    out.push_str("      connect('.e_phoff', '.bin_phdr0');\n");
    out.push_str("      connect('.e_shoff', '.bin_shdr0');\n");
    for i in 0..elf.phdrs.len() {
        let _ = writeln!(
            out,
            "      connect('.bin_phdr{} > .p_offset', '.bin_segment{}');",
            i, i
        );
    }
    for (i, sh) in elf.shdrs.iter().enumerate() {
        let _ = writeln!(
            out,
            "      connect('.bin_shdr{} > .sh_offset', '.bin_section{}');",
            i, i
        );
        if sh.link != 0 {
            let _ = writeln!(
                out,
                "      connect('.bin_shdr{} > .sh_link', '.bin_shdr{}');",
                i, sh.link
            );
        }
    }
}

pub fn generate(elf: &Elf, path: &str, title: &str) -> String {
    let len = elf.contents.len();
    let mut out = String::with_capacity(len * 6 + 64 * 1024);
    out.push_str(HEAD1);
    let _ = writeln!(out, "    <title>{}</title>", title);
    out.push_str(HEAD2);
    file_info(&mut out, elf, path);
    offsets_column(&mut out, len);
    bytes_column(&mut out, elf);
    ascii_column(&mut out, elf.contents);
    info_tables(&mut out, elf);
    out.push_str(SCRIPTS1);
    out.push_str("    <script type='text/javascript'>\n");
    let _ = writeln!(out, "      let fileLen = {}", len);
    out.push_str(OFFSETS_SCRIPT);
    out.push_str(ARROWS1);
    arrows(&mut out, elf);
    out.push_str(TAIL);
    out
}
